		assert.match(
			command,
			/--strict-mcp-config --tools 'Read' --settings '[^']+' --mcp-config '[^']+claude-mcp\.json'/,
		);
		assert.match(
			command,
			/--resume '33333333-3333-4333-8333-333333333333' '\[pi-subagent-turn:t\] next'$/,
		);
		assert.doesNotMatch(command, /--session-id/);
		const mcp = JSON.parse(readFileSync(run.mcpConfigFile!, "utf8"));
		assert.deepEqual(Object.keys(mcp.mcpServers), ["pi-subagents"]);
