		assert.equal(run.profileName, agentName);
		assert.match(
			kiroCommand(run, "[pi-subagent-turn:t] x"),
			/--agent 'pi-subagent-12345678-1234-4234-8234-123456789012' --trust-all-tools --resume-id '66666666-6666-4666-8666-666666666666'/,
		);
